import { sendEmail } from './_lib.js';
import { nyParts } from './_weekly.js';
import { nyDayBounds, REPORT_TO } from './_friday_report.js';
import { gradeFromBrief, hasGrade, normLetter, LETTERS } from './_grade.js';
import { hasIcpGrade, icpGradeFromBrief, icpLetter } from './_icp.js';

// ---------- Monday report (Olivier, 2026-11-26) ----------
// "Monday reports about talking points, how many generated by client with grades. All talking have a
// matching grade." Every Monday (first hourly run from 8 AM New York time; Tuesday as fallback) one email
// goes to report@gershonconsulting.com: talking points generated per client during the previous week
// (Monday–Sunday, New York time), each with its Social Network Effectiveness Grade, plus the grade mix.
// Before counting, every saved talking point without a grade gets one (functions/_grade.js), so the report
// always shows 100% graded. Once per Monday: claim row MONDAY_REPORT_SENT:<monday> + Resend idempotency key.

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const addDays = (day, n) => new Date(Date.parse(`${day}T12:00:00Z`) + n * 864e5).toISOString().slice(0, 10);

// Gives a grade to every saved talking point that has none. Returns how many were filled.
export async function ensureGrades(env) {
  const rows = (await env.DB.prepare('SELECT id, data FROM briefs').all()).results;
  let filled = 0;
  for (const r of rows) {
    let data;
    try { data = JSON.parse(r.data || '{}'); } catch { continue; }
    const needSocial = !hasGrade(data), icp = hasIcpGrade(data) ? null : icpGradeFromBrief(data);
    if (!needSocial && !icp) continue;
    if (needSocial) data.grade = gradeFromBrief(data);
    if (icp) data.icp_grade = icp;
    await env.DB.prepare('UPDATE briefs SET data = ? WHERE id = ?').bind(JSON.stringify(data), r.id).run();
    filled++;
  }
  return filled;
}

// `monday` = the Monday the report is sent ('YYYY-MM-DD'); it covers the 7 days before it.
export async function buildMondayReport(env, monday, { filled = 0 } = {}) {
  const weekStart = addDays(monday, -7), weekEnd = addDays(monday, -1);
  const [from] = nyDayBounds(weekStart);
  const [to] = nyDayBounds(monday);
  const clients = (await env.DB.prepare('SELECT id, name FROM clients ORDER BY name').all()).results;
  const briefs = (await env.DB.prepare(
    'SELECT client_id, company, lead_name, status, data, created_at FROM briefs WHERE created_at >= ? AND created_at < ? ORDER BY created_at'
  ).bind(from, to).all()).results;
  const totals = Object.fromEntries((await env.DB.prepare('SELECT client_id, COUNT(*) AS n FROM briefs GROUP BY client_id').all()).results.map((r) => [r.client_id, r.n]));

  const mix = Object.fromEntries(LETTERS.map((l) => [l, 0]));
  const icpMix = Object.fromEntries(LETTERS.map((l) => [l, 0]));
  let ungraded = 0;
  const rows = clients.map((c) => {
    const items = briefs.filter((b) => b.client_id === c.id).map((b) => {
      let d = {}; try { d = JSON.parse(b.data || '{}'); } catch { d = {}; }
      const letter = hasGrade(d) ? normLetter(d.grade.letter) : null;
      if (letter) mix[letter]++; else ungraded++;
      const icp = icpLetter(d);
      if (icp) icpMix[icp]++;
      return { icp, company: b.company || d.header?.company || '—', lead: b.lead_name || d.header?.person || '', letter, kind: d.auto ? 'AI' : 'researched' };
    });
    const g = {}; for (const i of items) if (i.letter) g[i.letter] = (g[i.letter] || 0) + 1;
    return { name: c.name, count: items.length, total: totals[c.id] || 0, items, grades: LETTERS.filter((l) => g[l]).map((l) => `${l}×${g[l]}`).join(' ') };
  }).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));

  const total = briefs.length;
  const withAny = rows.filter((r) => r.count).length;
  const fmtDay = (d, y) => new Date(`${d}T12:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', ...(y ? { year: 'numeric' } : {}), timeZone: 'UTC' });
  const range = `${fmtDay(weekStart)} – ${fmtDay(weekEnd, true)}`;
  const subject = `Talking Points Report — ${range} (Monday report)`;

  const td = 'padding:8px 10px;border-bottom:1px solid #e9ecef;vertical-align:top;font-size:13px;color:#1a1a1a;';
  const th = 'padding:8px 10px;border-bottom:2px solid #FE1B04;text-align:left;font-size:11px;letter-spacing:.8px;text-transform:uppercase;color:#5f6b76;';
  const chip = (l) => `<span style="display:inline-block;min-width:26px;text-align:center;background:#eef1f5;color:#FE1B04;font-weight:800;font-size:12px;padding:2px 6px;border-radius:10px;margin-right:6px;">${esc(l || '?')}</span>`;
  const body = rows.map((r) => `<tr>
<td style="${td}font-weight:700;">${esc(r.name)}<br><span style="font-weight:400;color:#5f6b76;font-size:12px;">${r.total} to date</span></td>
<td style="${td}text-align:center;font-weight:800;font-size:16px;color:${r.count ? '#FE1B04' : '#9aa3ab'};">${r.count}</td>
<td style="${td}white-space:nowrap;">${esc(r.grades) || '—'}</td>
<td style="${td}">${r.items.map((i) => `${chip(i.icp ? `ICP ${i.icp}` : 'ICP ?')}${chip(i.letter)}${esc(i.company)}${i.lead ? ` <span style="color:#5f6b76;">(${esc(i.lead)})</span>` : ''}${i.kind === 'AI' ? ' <span style="color:#9aa3ab;font-size:11px;">AI</span>' : ''}`).join('<br>') || '<span style="color:#9aa3ab;">—</span>'}</td>
</tr>`).join('');
  const mixLine = LETTERS.filter((l) => mix[l]).map((l) => `${chip(l)}${mix[l]}`).join(' &nbsp;') || '—';
  const icpLine = LETTERS.filter((l) => icpMix[l]).map((l) => `${chip(l)}${icpMix[l]}`).join(' &nbsp;') || '—';

  const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:760px;margin:0 auto;color:#1a1a1a;">
<div style="border-top:4px solid #FE1B04;padding:18px 0 8px;">
<div style="font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:#FE1B04;font-weight:700;">talkingpoints.gershon.ai · Monday report</div>
<div style="font-size:22px;font-weight:800;margin:4px 0;">Week of ${esc(range)}</div>
<div style="font-size:15px;color:#333;"><b style="color:#FE1B04;font-size:20px;">${total}</b> talking point${total === 1 ? '' : 's'} generated for <b>${withAny}</b> client${withAny === 1 ? '' : 's'} · <b>${total - ungraded}/${total}</b> graded${ungraded ? ` · <b style="color:#c0392b;">${ungraded} without grade</b>` : ''}.</div>
<div style="font-size:13px;color:#333;margin-top:8px;"><b>ICP match</b> mix: ${icpLine}</div>
<div style="font-size:13px;color:#333;margin-top:6px;">Social grade mix: ${mixLine}</div>
</div>
<table style="width:100%;border-collapse:collapse;margin-top:12px;">
<tr><th style="${th}">Client</th><th style="${th}text-align:center;">Generated</th><th style="${th}">Grades</th><th style="${th}">Talking points (ICP match · social grade · company · lead)</th></tr>
${body}
<tr><td style="${td}font-weight:800;border-top:2px solid #1a1a1a;">Total</td><td style="${td}text-align:center;font-weight:800;font-size:16px;border-top:2px solid #1a1a1a;">${total}</td><td style="${td}border-top:2px solid #1a1a1a;"></td><td style="${td}border-top:2px solid #1a1a1a;"></td></tr>
</table>
<p style="font-size:12px;color:#5f6b76;margin-top:16px;">ICP match = fit with the client's Ideal Customer Profile (A+ strong … D outside it). Social grade = Social Network Effectiveness (A+ six-figure audiences across several networks … D little or no presence). AI = built by Cloudflare AI; its grade is computed from the channels on the lead's website and their public follower counts.${filled ? ` ${filled} older talking point${filled === 1 ? '' : 's'} had no grade and got one this morning.` : ''} Details: <a href="https://talkingpoints.gershon.ai/app#admin" style="color:#FE1B04;">Admin</a>.</p>
</div>`;

  const text = [`Talking Points — Monday report — week of ${range}`, `${total} talking points generated for ${withAny} clients, ${total - ungraded}/${total} graded.`, '',
    ...rows.map((r) => `${r.name}: ${r.count}${r.grades ? ` [${r.grades}]` : ''}${r.items.length ? ` — ${r.items.map((i) => `ICP ${i.icp || '?'}/${i.letter || '?'} ${i.company}`).join('; ')}` : ''}`)].join('\n');

  return { monday, week: [weekStart, weekEnd], subject, html, text, total, ungraded, mix, icpMix, clients: rows };
}

export async function sendMondayOnce(env, monday, rep, send = sendEmail) {
  const claim = `MONDAY_REPORT_SENT:${monday}`;
  const got = await env.DB.prepare('INSERT OR IGNORE INTO app_secrets (name, value) VALUES (?, ?)').bind(claim, new Date().toISOString()).run();
  if (!got?.meta?.changes) return false;
  try {
    await send(env, { to: [REPORT_TO], subject: rep.subject, html: rep.html, text: rep.text, from: 'GC Talking Points <talkingpoints@gershon.ai>', idempotencyKey: `tp-monday-${monday}` });
  } catch (e) {
    await env.DB.prepare('DELETE FROM app_secrets WHERE name = ?').bind(claim).run();
    throw e;
  }
  return true;
}

// Called at the end of every hourly cron run.
export async function maybeSendMondayReport(env, { send = sendEmail, now = nyParts() } = {}) {
  let monday = null;
  if (now.weekday === 'Mon' && now.hour >= 8) monday = now.day;
  else if (now.weekday === 'Tue') monday = addDays(now.day, -1);
  if (!monday) return null;
  const done = await env.DB.prepare('SELECT value FROM app_secrets WHERE name = ?').bind(`MONDAY_REPORT_SENT:${monday}`).first();
  if (done) return null;
  const filled = await ensureGrades(env);
  const rep = await buildMondayReport(env, monday, { filled });
  if (!(await sendMondayOnce(env, monday, rep, send))) return null;
  return { sent_to: REPORT_TO, monday, total: rep.total, graded_now: filled };
}
